  gap: 7px;
  width: fit-content;
  padding: 7px 11px;
  border: 1px solid var(--art-border);
  border-radius: 999px;
  background: var(--art-surface);
  color: var(--art-muted);
  font-size: 12px;
  white-space: nowrap;
}
.pill::before { content: ''; width: 7px; height: 7px; border-radius: 50%; background: var(--art-accent); }
.workspace { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(250px, 0.75fr); gap: 16px; align-items: stretch; }
.stage, .panel, .timeline {
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius);
  background: var(--art-surface);
  box-shadow: var(--art-shadow);
  backdrop-filter: blur(14px);
}
.stage { position: relative; min-height: 330px; padding: 22px; overflow: hidden; }
.stage::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image: linear-gradient(var(--art-grid) 1px, transparent 1px), linear-gradient(90deg, var(--art-grid) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: linear-gradient(to bottom, black, transparent 88%);
}
.panel { padding: 18px; display: grid; gap: 14px; align-content: start; }
.panel h2 { margin-bottom: 2px; }
.field { display: grid; gap: 7px; }
.field label, .field-label { color: var(--art-muted); font-size: 12px; font-weight: 650; }
select, input[type='range'] {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: var(--art-surface-raised);
  padding: 9px 11px;
}
input[type='range'] { padding: 0; accent-color: var(--art-accent); }
.button-row { display: flex; flex-wrap: wrap; gap: 8px; }
button {
  min-height: 40px;
  padding: 9px 13px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: var(--art-surface-raised);
  color: var(--art-ink);
  font-weight: 650;
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease, box-shadow 160ms ease;
}
button:hover:not(:disabled) { transform: translateY(-1px); border-color: var(--art-accent); box-shadow: 0 7px 18px var(--art-accent-soft); }
button:active:not(:disabled) { transform: translateY(0); }
button[data-active='true'], button.primary {
  border-color: transparent;
  background: var(--art-accent);
  color: #fff;
}
button[data-active='true']:hover, button.primary:hover { background: var(--art-accent-strong); }
.metric-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 9px; }
.metric { padding: 12px; border: 1px solid var(--art-border); border-radius: var(--art-radius-sm); background: var(--art-surface-raised); }
.metric strong { display: block; margin-bottom: 3px; font-size: 20px; letter-spacing: -0.02em; }
.metric span { color: var(--art-muted); font-size: 11px; }
.result {
  min-height: 54px;
  padding: 13px 14px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: var(--art-surface-raised);
  color: var(--art-muted);
}
.result[data-tone='good'] { border-color: transparent; background: var(--art-good-soft); color: var(--art-good); }
.result[data-tone='warn'] { border-color: transparent; background: var(--art-warn-soft); color: var(--art-warn); }
.result[data-tone='bad'] { border-color: transparent; background: var(--art-bad-soft); color: var(--art-bad); }
.feedback {
  padding: 14px 16px;
  border-left: 3px solid var(--art-good);
  border-radius: var(--art-radius-sm);
  background: var(--art-good-soft);
  color: var(--art-good);
  font-weight: 650;
}
.timeline { padding: 16px 18px; display: flex; flex-wrap: wrap; gap: 14px; align-items: center; }
.step { display: inline-flex; align-items: center; gap: 7px; color: var(--art-muted); font-size: 12px; }
.step::before { content: ''; width: 8px; height: 8px; border: 1px solid var(--art-muted); border-radius: 50%; }
.step[data-state='done'] { color: var(--art-good); }
.step[data-state='done']::before { border-color: var(--art-good); background: var(--art-good); }
.step[data-state='current'] { color: var(--art-accent); }
.step[data-state='current']::before { border-color: var(--art-accent); background: var(--art-accent); box-shadow: 0 0 0 4px var(--art-accent-soft); }
.chart { display: block; width: 100%; height: 230px; border-radius: var(--art-radius-sm); background: var(--art-surface-raised); }
.motion-enter { animation: art-enter 420ms cubic-bezier(0.2, 0.8, 0.2, 1) both; }
.motion-highlight { animation: art-highlight 560ms cubic-bezier(0.2, 0.8, 0.2, 1); }
@keyframes art-enter { from { opacity: 0; transform: translateY(9px); } to { opacity: 1; transform: translateY(0); } }
@keyframes art-highlight { 0% { box-shadow: 0 0 0 0 var(--art-accent-soft); } 45% { box-shadow: 0 0 0 8px var(--art-accent-soft); } 100% { box-shadow: 0 0 0 0 var(--art-accent-soft); } }
@media (max-width: 780px) {
  .lab { padding: 18px; }
  .hero, .workspace { grid-template-columns: 1fr; }
  .stage { min-height: 290px; }
  .metric-row { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 1ms !important; transition-duration: 1ms !important; scroll-behavior: auto !important; }
