  <script>
/* Small, one-shot motion primitives. Inline this file into an Artifact; no imports. */
function reducedMotion() {
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

function beat(elements, { staggerMs = 70 } = {}) {
  const list = Array.from(elements)
  if (reducedMotion()) {
    for (const element of list) element.dataset.beat = 'done'
    return
  }
  for (const [index, element] of list.entries()) {
    element.classList.add('motion-enter')
    element.style.animationDelay = `${index * staggerMs}ms`
    element.addEventListener('animationend', () => { element.dataset.beat = 'done' }, { once: true })
  }
}

function highlight(element) {
  if (!element) return
  if (reducedMotion()) return
  element.classList.remove('motion-highlight')
  void element.offsetWidth
  element.classList.add('motion-highlight')
}

function tween({ from, to, duration = 420, update, done }) {
  if (reducedMotion()) {
    update(to)
    done?.()
    return () => {}
  }
  const start = performance.now()
  let frame = 0
  const step = (now) => {
    const progress = Math.min(1, (now - start) / duration)
    const eased = 1 - Math.pow(1 - progress, 3)
    update(from + (to - from) * eased)
    if (progress < 1) frame = requestAnimationFrame(step)
    else done?.()
  }
  frame = requestAnimationFrame(step)
  return () => cancelAnimationFrame(frame)
}

</script>
  <script>
    let angle = 45
    let prediction = null
    const result = document.getElementById('result')
    const angleInput = document.getElementById('angle')
    const hitButton = document.getElementById('predict-hit')
    const missButton = document.getElementById('predict-miss')

    function setPrediction(value) {
      prediction = value
      hitButton.dataset.active = String(value === true)
      missButton.dataset.active = String(value === false)
      hitButton.setAttribute('aria-pressed', String(value === true))
      missButton.setAttribute('aria-pressed', String(value === false))
      result.dataset.tone = ''
      result.textContent = `Prediction: ${value ? 'hit' : 'miss'}`
      highlight(result)
    }

    hitButton.addEventListener('click', () => { setPrediction(true) })
    missButton.addEventListener('click', () => { setPrediction(false) })
    angleInput.addEventListener('change', () => { angle = Number(angleInput.value) })
    document.getElementById('launch').addEventListener('click', () => {
      if (prediction === null) {
        result.dataset.tone = 'warn'
        result.textContent = 'Choose a prediction first'
        highlight(result)
        return
      }
      const actualHit = angle === 45
      const matched = prediction === actualHit
      result.dataset.tone = matched ? 'good' : 'warn'
      result.textContent = `Actual: ${actualHit ? 'hit' : 'miss'} — ${matched ? 'prediction matched' : 'prediction differed'}`
      for (const step of document.querySelectorAll('.timeline .step')) step.dataset.state = 'done'
      highlight(result)
      parent.postMessage({
        kind: 'artifact-action', artifactId: 'projectile-lab', revision: 1,
        action: 'shot.completed', payload: { angle, predictedHit: prediction, actualHit },
      }, '*')
    })

    beat(document.querySelectorAll('.hero, .workspace, .timeline'))
  </script>
